package com.singtel.platformcommon;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.transaction.annotation.Propagation;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.beans.factory.annotation.Value;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;import java.time.Instant;import org.slf4j.LoggerFactory;
@Service public class Events{private final OutboxRepository repo;private final ObjectMapper mapper;private final KafkaTemplate<String,String> kafka;private final boolean enabled;public Events(OutboxRepository r,ObjectMapper m,KafkaTemplate<String,String> k,@Value("${platform.events-enabled:false}")boolean e){repo=r;mapper=m;kafka=k;enabled=e;}
 @Transactional(propagation=Propagation.MANDATORY)public void append(String aggregate,String type,Object data){try{String id=UUID.randomUUID().toString();repo.save(new OutboxEvent(aggregate,"promotion.events.v1",mapper.writeValueAsString(Map.of("eventId",id,"schemaVersion",1,"type",type,"aggregateId",aggregate,"occurredAt",Instant.now().toString(),"data",data))));}catch(Exception e){throw new IllegalStateException("Cannot serialize domain event",e);}}
 @Scheduled(fixedDelay=5000)public void publish(){if(!enabled)return;for(var event:repo.findTop100ByPublishedAtIsNullOrderByCreatedAtAsc()){try{kafka.send(event.topic,event.aggregateId,event.payload).get(12,java.util.concurrent.TimeUnit.SECONDS);event.publishedAt=Instant.now();event.attempts++;repo.save(event);}catch(Exception e){LoggerFactory.getLogger(Events.class).warn("Outbox publish deferred eventId={}",event.id);break;}}}
}
